import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

export function resolveDataPath(customPath) {
  if (customPath) return path.resolve(customPath);
  if (process.env.BOOKS_FILE) return path.resolve(process.env.BOOKS_FILE);
  if (process.env.DATA_FILE) return path.resolve(process.env.DATA_FILE);
  return path.resolve(process.cwd(), 'books.json');
}

export class BookStore {
  constructor(filePath) {
    this.filePath = resolveDataPath(filePath);
    this._ensureFile();
  }

  _ensureFile() {
    const dir = path.dirname(this.filePath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    if (!fs.existsSync(this.filePath)) {
      fs.writeFileSync(this.filePath, JSON.stringify([], null, 2), 'utf8');
    }
  }

  _readAll() {
    this._ensureFile();
    try {
      const raw = fs.readFileSync(this.filePath, 'utf8').trim();
      if (!raw) return [];
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) return parsed;
      if (parsed && Array.isArray(parsed.books)) return parsed.books;
      return [];
    } catch {
      return [];
    }
  }

  _writeAll(books) {
    const dir = path.dirname(this.filePath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    fs.writeFileSync(this.filePath, JSON.stringify(books, null, 2), 'utf8');
  }

  getAll() {
    return this._readAll().map((b) => this._normalize(b));
  }

  getById(id) {
    const books = this.getAll();
    return books.find((b) => String(b.id) === String(id)) || null;
  }

  add({ title, author, notes = '', status, finished = false }) {
    const cleanTitle = String(title || '').trim();
    const cleanAuthor = String(author || '').trim();
    const cleanNotes = String(notes || '').trim();

    if (!cleanTitle) {
      throw new Error('Title is required');
    }
    if (!cleanAuthor) {
      throw new Error('Author is required');
    }

    const isFinished = status === 'finished' || Boolean(finished);
    const books = this._readAll();
    const book = this._normalize({
      id: crypto.randomUUID().slice(0, 8),
      title: cleanTitle,
      author: cleanAuthor,
      notes: cleanNotes,
      status: isFinished ? 'finished' : 'reading',
      finished: isFinished,
      createdAt: new Date().toISOString(),
      finishedAt: isFinished ? new Date().toISOString() : null,
    });

    books.push(book);
    this._writeAll(books);
    return book;
  }

  update(id, patch = {}) {
    const books = this._readAll();
    const idx = books.findIndex((b) => String(b.id) === String(id));
    if (idx === -1) return null;

    const existing = this._normalize(books[idx]);
    const nextFinished =
      patch.status !== undefined
        ? patch.status === 'finished'
        : patch.finished !== undefined
          ? Boolean(patch.finished)
          : existing.finished;

    const updated = this._normalize({
      ...existing,
      title: patch.title !== undefined ? String(patch.title).trim() || existing.title : existing.title,
      author: patch.author !== undefined ? String(patch.author).trim() || existing.author : existing.author,
      notes: patch.notes !== undefined ? String(patch.notes).trim() : existing.notes,
      status: nextFinished ? 'finished' : 'reading',
      finished: nextFinished,
      finishedAt: nextFinished ? existing.finishedAt || new Date().toISOString() : null,
    });

    books[idx] = updated;
    this._writeAll(books);
    return updated;
  }

  markFinished(id) {
    return this.update(id, { status: 'finished', finished: true });
  }

  delete(id) {
    const books = this._readAll();
    const next = books.filter((b) => String(b.id) !== String(id));
    if (next.length === books.length) return false;
    this._writeAll(next);
    return true;
  }

  _normalize(b) {
    const isFinished = b.status === 'finished' || Boolean(b.finished);
    return {
      id: String(b.id),
      title: String(b.title || ''),
      author: String(b.author || ''),
      notes: String(b.notes || ''),
      status: isFinished ? 'finished' : 'reading',
      finished: isFinished,
      createdAt: b.createdAt || new Date().toISOString(),
      finishedAt: isFinished ? b.finishedAt || new Date().toISOString() : null,
    };
  }
}

