import http from 'node:http';
import { URL } from 'node:url';
import { BookStore } from './store.js';

function escapeHtml(str) {
  return String(str ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

const STYLES = `
  :root {
    --bg: #f8fafc;
    --surface: #ffffff;
    --border: #e2e8f0;
    --text: #0f172a;
    --muted: #64748b;
    --primary: #2563eb;
    --primary-hover: #1d4ed8;
    --success-bg: #dcfce7;
    --success-text: #166534;
    --reading-bg: #dbeafe;
    --reading-text: #1e40af;
    --shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.08), 0 1px 2px -1px rgba(0, 0, 0, 0.06);
  }
  * {
    box-sizing: border-box;
  }
  body {
    margin: 0;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background-color: var(--bg);
    color: var(--text);
    line-height: 1.5;
  }
  .container {
    max-width: 900px;
    margin: 0 auto;
    padding: 2rem 1.25rem 4rem;
  }
  header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 2rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid var(--border);
  }
  header h1 {
    margin: 0;
    font-size: 1.75rem;
    font-weight: 700;
    letter-spacing: -0.025em;
  }
  header h1 a {
    color: var(--text);
    text-decoration: none;
  }
  .subtitle {
    margin: 0.25rem 0 0;
    color: var(--muted);
    font-size: 0.95rem;
  }
  .card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 0.75rem;
    padding: 1.5rem;
    box-shadow: var(--shadow);
    margin-bottom: 2rem;
  }
  .card h2 {
    margin-top: 0;
    margin-bottom: 1rem;
    font-size: 1.25rem;
  }
  .form-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
  }
  @media (max-width: 640px) {
    .form-grid {
      grid-template-columns: 1fr;
    }
  }
  .field {
    display: flex;
    flex-direction: column;
    gap: 0.375rem;
    margin-bottom: 1rem;
  }
  .field.full {
    grid-column: 1 / -1;
  }
  label {
    font-size: 0.875rem;
    font-weight: 600;
    color: var(--text);
  }
  input[type="text"],
  textarea {
    width: 100%;
    padding: 0.625rem 0.75rem;
    border: 1px solid var(--border);
    border-radius: 0.5rem;
    font-size: 0.95rem;
    font-family: inherit;
    background: #fff;
    color: var(--text);
  }
  input[type="text"]:focus,
  textarea:focus {
    outline: 2px solid var(--primary);
    border-color: transparent;
  }
  textarea {
    min-height: 88px;
    resize: vertical;
  }
  .btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    padding: 0.55rem 1rem;
    font-size: 0.9rem;
    font-weight: 600;
    border-radius: 0.5rem;
    border: 1px solid transparent;
    cursor: pointer;
    text-decoration: none;
    transition: background-color 0.15s ease, border-color 0.15s ease;
  }
  .btn-primary {
    background-color: var(--primary);
    color: #fff;
  }
  .btn-primary:hover {
    background-color: var(--primary-hover);
  }
  .btn-secondary {
    background-color: #fff;
    color: var(--text);
    border-color: var(--border);
  }
  .btn-secondary:hover {
    background-color: #f1f5f9;
  }
  .btn-success {
    background-color: #16a34a;
    color: #fff;
  }
  .btn-success:hover {
    background-color: #15803d;
  }
  .sections-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1.5rem;
  }
  @media (max-width: 720px) {
    .sections-grid {
      grid-template-columns: 1fr;
    }
  }
  .section-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 1rem;
  }
  .section-header h2 {
    margin: 0;
    font-size: 1.25rem;
  }
  .badge {
    display: inline-block;
    padding: 0.2rem 0.6rem;
    border-radius: 999px;
    font-size: 0.78rem;
    font-weight: 600;
  }
  .badge-reading {
    background: var(--reading-bg);
    color: var(--reading-text);
  }
  .badge-finished {
    background: var(--success-bg);
    color: var(--success-text);
  }
  .book-list {
    list-style: none;
    padding: 0;
    margin: 0;
    display: flex;
