function renderLayout(title, bodyContent) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>${escapeHtml(title)} — Reading Tracker</title>
  <style>${STYLES}</style>
</head>
<body>
  <div class="container">
    <header>
      <div>
        <h1><a href="/">Reading Tracker</a></h1>
        <p class="subtitle">Keep track of what you're currently reading and books you've finished.</p>
      </div>
    </header>
    <main id="app">
      ${bodyContent}
    </main>
  </div>
</body>
</html>`;
}

function renderBookItem(book) {
  const href = `/books/${encodeURIComponent(book.id)}`;
  const isFinished = book.status === 'finished' || book.finished;

  return `
    <li class="book-item" data-book-id="${escapeHtml(book.id)}" data-status="${isFinished ? 'finished' : 'reading'}">
      <div class="book-item-header">
        <div>
          <h3 class="book-title">
            <a href="${href}" class="book-link">${escapeHtml(book.title)}</a>
          </h3>
          <p class="book-author">by <span class="author-name">${escapeHtml(book.author)}</span></p>
        </div>
        <span class="badge ${isFinished ? 'badge-finished' : 'badge-reading'}">
          ${isFinished ? 'Finished' : 'Currently Reading'}
        </span>
      </div>
      ${book.notes ? `<p class="book-notes-preview">${escapeHtml(book.notes)}</p>` : ''}
      <div class="book-actions">
        <a href="${href}" class="btn btn-secondary">View Details</a>
        ${
          !isFinished
            ? `<form class="inline-form mark-finished-form" method="POST" action="/books/${encodeURIComponent(book.id)}/finish" data-book-id="${escapeHtml(book.id)}">
                <button type="submit" class="btn btn-success mark-finished-btn" data-book-id="${escapeHtml(book.id)}">Mark as Finished</button>
              </form>`
            : ''
        }
      </div>
    </li>
  `;
}

function renderHomePage(books) {
  const currentlyReading = books.filter((b) => !(b.status === 'finished' || b.finished));
  const finishedBooks = books.filter((b) => b.status === 'finished' || b.finished);

  const content = `
    <section class="card" aria-labelledby="add-book-heading">
      <h2 id="add-book-heading">Add a Book</h2>
      <form id="add-book-form" method="POST" action="/books">
        <div class="form-grid">
          <div class="field">
            <label for="title-input">Title</label>
            <input id="title-input" name="title" type="text" placeholder="e.g. The Left Hand of Darkness" required />
          </div>
          <div class="field">
            <label for="author-input">Author</label>
            <input id="author-input" name="author" type="text" placeholder="e.g. Ursula K. Le Guin" required />
          </div>
          <div class="field full">
            <label for="notes-input">Notes</label>
            <textarea id="notes-input" name="notes" placeholder="Thoughts, favorite quotes, or chapter notes..."></textarea>
          </div>
        </div>
        <button type="submit" class="btn btn-primary">Add Book</button>
      </form>
    </section>

    <div class="sections-grid">
      <section id="currently-reading" data-section="currently-reading" aria-labelledby="reading-heading">
        <div class="section-header">
          <h2 id="reading-heading">Currently Reading</h2>
          <span class="badge badge-reading" id="reading-count">${currentlyReading.length}</span>
        </div>
        ${
          currentlyReading.length > 0
            ? `<ul class="book-list" id="reading-list">${currentlyReading.map(renderBookItem).join('')}</ul>`
            : `<div class="empty-state" id="reading-empty">No books currently being read. Add one above!</div>`
        }
      </section>

      <section id="finished-books" data-section="finished" aria-labelledby="finished-heading">
        <div class="section-header">
          <h2 id="finished-heading">Finished</h2>
          <span class="badge badge-finished" id="finished-count">${finishedBooks.length}</span>
        </div>
        ${
          finishedBooks.length > 0
            ? `<ul class="book-list" id="finished-list">${finishedBooks.map(renderBookItem).join('')}</ul>`
            : `<div class="empty-state" id="finished-empty">No finished books yet.</div>`
        }
      </section>
    </div>

    <script>
      (function() {
        const addForm = document.getElementById('add-book-form');
        if (addForm) {
          addForm.addEventListener('submit', async function(e) {
            e.preventDefault();
            const formData = new FormData(addForm);
            const payload = {
              title: formData.get('title'),
              author: formData.get('author'),
              notes: formData.get('notes') || ''
            };
            const res = await fetch('/api/books', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
              body: JSON.stringify(payload)
            });
            if (res.ok) {
              window.location.reload();
            }
          });
        }

        document.querySelectorAll('.mark-finished-form').forEach(function(form) {
          form.addEventListener('submit', async function(e) {
            e.preventDefault();
            const bookId = form.getAttribute('data-book-id');
            const res = await fetch('/api/books/' + encodeURIComponent(bookId) + '/finish', {
              method: 'POST',
              headers: { 'Accept': 'application/json' }
            });
            if (res.ok) {
              window.location.reload();
            }
          });
        });
      })();
    </script>
  `;

  return renderLayout('Home', content);
}

function renderBookDetailPage(book, origin = '') {
  const isFinished = book.status === 'finished' || book.finished;
  const sharePath = `/books/${encodeURIComponent(book.id)}`;
  const shareUrl = origin ? `${origin}${sharePath}` : sharePath;

  const content = `
    <a href="/" class="back-link">&larr; Back to all books</a>

    <article class="card" data-book-detail="${escapeHtml(book.id)}">
      <div class="detail-header">
        <div>
          <h2 class="detail-title" id="book-title">${escapeHtml(book.title)}</h2>
          <p class="detail-author" id="book-author">by <span>${escapeHtml(book.author)}</span></p>
        </div>
        <span class="badge ${isFinished ? 'badge-finished' : 'badge-reading'}" id="book-status">
          ${isFinished ? 'Finished' : 'Currently Reading'}
        </span>
      </div>

      <section aria-labelledby="notes-heading">
        <h3 id="notes-heading" style="font-size: 1rem; margin-bottom: 0.4rem;">My Notes</h3>
        <div class="notes-box" id="book-notes">${book.notes ? escapeHtml(book.notes) : 'No notes added yet.'}</div>
      </section>

      <div class="book-actions">
        ${
          !isFinished
            ? `<form id="detail-finish-form" class="inline-form" method="POST" action="/books/${encodeURIComponent(book.id)}/finish">
                <button type="submit" class="btn btn-success" id="detail-finish-btn">Mark as Finished</button>
              </form>`
            : ''
        }
      </div>

      <details style="margin-top: 1.25rem;">
        <summary style="cursor: pointer; font-weight: 600; font-size: 0.9rem; color: var(--primary);">Edit Notes</summary>
        <form id="update-notes-form" method="POST" action="/books/${encodeURIComponent(book.id)}/notes" style="margin-top: 0.75rem;">
          <div class="field">
            <label for="edit-notes-textarea">Notes</label>
            <textarea id="edit-notes-textarea" name="notes">${escapeHtml(book.notes)}</textarea>
          </div>
          <button type="submit" class="btn btn-primary">Save Notes</button>
        </form>
      </details>

      <div class="share-box">
        <label for="share-link-input">Share link to this book:</label>
        <input id="share-link-input" class="share-input" type="text" readonly value="${escapeHtml(shareUrl)}" />
        <button type="button" class="btn btn-secondary" id="copy-link-btn">Copy Link</button>
      </div>
    </article>

    <script>
      (function() {
        const shareInput = document.getElementById('share-link-input');
        if (shareInput && shareInput.value.startsWith('/')) {
          shareInput.value = window.location.origin + shareInput.value;
        }
        const copyBtn = document.getElementById('copy-link-btn');
        if (copyBtn && shareInput) {
          copyBtn.addEventListener('click', function() {
            if (navigator.clipboard && navigator.clipboard.writeText) {
              navigator.clipboard.writeText(shareInput.value);
            } else {
              shareInput.select();
              document.execCommand('copy');
            }
            copyBtn.textContent = 'Copied!';
          });
        }
        const finishForm = document.getElementById('detail-finish-form');
        if (finishForm) {
          finishForm.addEventListener('submit', async function(e) {
            e.preventDefault();
            const res = await fetch('/api/books/${encodeURIComponent(book.id)}/finish', {
              method: 'POST',
              headers: { 'Accept': 'application/json' }
            });
            if (res.ok) {
              window.location.reload();
            }
          });
        }
        const notesForm = document.getElementById('update-notes-form');
        if (notesForm) {
          notesForm.addEventListener('submit', async function(e) {
            e.preventDefault();
            const notes = document.getElementById('edit-notes-textarea').value;
            const res = await fetch('/api/books/${encodeURIComponent(book.id)}', {
              method: 'PATCH',
              headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
              body: JSON.stringify({ notes })
            });
            if (res.ok) {
              window.location.reload();
            }
          });
        }
      })();
    </script>
  `;

  return renderLayout(book.title, content);
}

function renderNotFoundPage() {
  const content = `
    <div class="card" style="text-align: center; padding: 3rem 1.5rem;">
      <h2>Book Not Found</h2>
      <p style="color: var(--muted); margin-bottom: 1.5rem;">The book you're looking for doesn't exist or may have been removed.</p>
      <a href="/" class="btn btn-primary">Back to Reading List</a>
    </div>
  `;
  return renderLayout('Not Found', content);
}

function parseBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    req.on('data', (chunk) => chunks.push(chunk));
    req.on('end', () => {
      const raw = Buffer.concat(chunks).toString('utf8');
      if (!raw) return resolve({});
      const contentType = (req.headers['content-type'] || '').toLowerCase();
      if (contentType.includes('application/json')) {
        try {
          return resolve(JSON.parse(raw));
        } catch (err) {
          return reject(new Error('Invalid JSON'));
        }
      }
      if (contentType.includes('application/x-www-form-urlencoded')) {
        const params = new URLSearchParams(raw);
        const obj = {};
        for (const [k, v] of params.entries()) {
          obj[k] = v;
        }
        return resolve(obj);
      }
      // Fallback: try JSON then form-urlencoded
      try {
        return resolve(JSON.parse(raw));
      } catch {
        const params = new URLSearchParams(raw);
        const obj = {};
        for (const [k, v] of params.entries()) {
          obj[k] = v;
        }
        return resolve(obj);
      }
    });
    req.on('error', reject);
  });
}

function sendJson(res, statusCode, data) {
  const payload = JSON.stringify(data);
  res.writeHead(statusCode, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(payload),
  });
  res.end(payload);
}

function sendHtml(res, statusCode, html) {
  res.writeHead(statusCode, {
    'Content-Type': 'text/html; charset=utf-8',
    'Content-Length': Buffer.byteLength(html),
  });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function wantsJson(req, pathname) {
  if (pathname.startsWith('/api/')) return true;
  const accept = (req.headers['accept'] || '').toLowerCase();
  if (accept.includes('application/json') && !accept.includes('text/html')) {
    return true;
  }
  return false;
}

export function createApp(options = {}) {
  const store = options.store || new BookStore(options.filePath || options.dataFile);

  const requestListener = async (req, res) => {
    try {
      const host = req.headers.host || 'localhost';
      const protocol = req.headers['x-forwarded-proto'] || 'http';
      const origin = `${protocol}://${host}`;
      const url = new URL(req.url || '/', origin);
      const pathname = url.pathname.replace(/\/+$/, '') || '/';
      const method = (req.method || 'GET').toUpperCase();

      // Home page
      if (method === 'GET' && pathname === '/') {
        const books = store.getAll();
        if (wantsJson(req, pathname)) {
          return sendJson(res, 200, books);
        }
        return sendHtml(res, 200, renderHomePage(books));
      }

      // API: List books
      if (method === 'GET' && pathname === '/api/books') {
        const books = store.getAll();
        return sendJson(res, 200, books);
      }

      // Create book (API or HTML form POST)
      if (method === 'POST' && (pathname === '/api/books' || pathname === '/books')) {
        let body;
        try {
          body = await parseBody(req);
        } catch {
          return sendJson(res, 400, { error: 'Invalid request body' });
        }

        try {
          const book = store.add({
            title: body.title,
            author: body.author,
            notes: body.notes,
            status: body.status,
            finished: body.finished,
          });
          if (wantsJson(req, pathname)) {
            return sendJson(res, 201, book);
          }
          return redirect(res, '/');
        } catch (err) {
          if (wantsJson(req, pathname)) {
            return sendJson(res, 400, { error: err.message });
          }
          return sendHtml(res, 400, renderLayout('Error', `<div class="card"><p>${escapeHtml(err.message)}</p><a href="/">Back</a></div>`));
        }
      }

      // Match /api/books/:id/finish or /books/:id/finish or /books/:id/complete
      const finishMatch = pathname.match(/^(?:\/api)?\/books\/([^/]+)\/(?:finish|complete)$/);
      if (finishMatch && (method === 'POST' || method === 'PATCH' || method === 'PUT')) {
        const id = decodeURIComponent(finishMatch[1]);
        const updated = store.markFinished(id);
        if (!updated) {
          return wantsJson(req, pathname)
            ? sendJson(res, 404, { error: 'Book not found' })
            : sendHtml(res, 404, renderNotFoundPage());
        }
        if (wantsJson(req, pathname)) {
          return sendJson(res, 200, updated);
        }
        const referer = req.headers.referer || '/';
        try {
          const refUrl = new URL(referer, origin);
          return redirect(res, refUrl.pathname || '/');
        } catch {
          return redirect(res, '/');
        }
      }

      // Match /books/:id/notes (HTML form POST to update notes)
      const notesMatch = pathname.match(/^\/books\/([^/]+)\/notes$/);
      if (notesMatch && method === 'POST') {
        const id = decodeURIComponent(notesMatch[1]);
        const body = await parseBody(req);
        const updated = store.update(id, { notes: body.notes ?? '' });
        if (!updated) {
          return sendHtml(res, 404, renderNotFoundPage());
        }
        return redirect(res, `/books/${encodeURIComponent(id)}`);
      }

      // Match /api/books/:id or /books/:id or /book/:id
      const bookMatch = pathname.match(/^(?:\/api)?\/books?\/([^/]+)$/);
      if (bookMatch) {
        const id = decodeURIComponent(bookMatch[1]);

        if (method === 'GET') {
          const book = store.getById(id);
          if (!book) {
            return wantsJson(req, pathname)
              ? sendJson(res, 404, { error: 'Book not found' })
              : sendHtml(res, 404, renderNotFoundPage());
          }
          if (wantsJson(req, pathname)) {
            return sendJson(res, 200, book);
          }
          return sendHtml(res, 200, renderBookDetailPage(book, origin));
        }

        if (method === 'PATCH' || method === 'PUT' || method === 'POST') {
          let body = {};
          try {
            body = await parseBody(req);
          } catch {
            return sendJson(res, 400, { error: 'Invalid request body' });
          }
          const updated = store.update(id, body);
          if (!updated) {
            return wantsJson(req, pathname)
              ? sendJson(res, 404, { error: 'Book not found' })
              : sendHtml(res, 404, renderNotFoundPage());
          }
          if (wantsJson(req, pathname)) {
            return sendJson(res, 200, updated);
          }
          return redirect(res, `/books/${encodeURIComponent(id)}`);
        }

        if (method === 'DELETE') {
          const deleted = store.delete(id);
          if (!deleted) {
            return sendJson(res, 404, { error: 'Book not found' });
          }
          return sendJson(res, 200, { ok: true });
        }
      }

      if (wantsJson(req, pathname)) {
        return sendJson(res, 404, { error: 'Not found' });
      }
      return sendHtml(res, 404, renderNotFoundPage());
    } catch (err) {
      if (!res.headersSent) {
        sendJson(res, 500, { error: err.message || 'Internal Server Error' });
      }
    }
  };

  const server = http.createServer(requestListener);
  server.store = store;
  return server;
}

import http from 'node:http';
import { URL } from 'node:url';
import { BookStore } from './store.js';

function escapeHtml(str) {
  return String(str ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

