import { fileURLToPath } from 'node:url';
import { createApp } from './src/app.js';
import { BookStore, resolveDataPath } from './src/store.js';

export { createApp, BookStore, resolveDataPath };

export function startServer(port = process.env.PORT || 3000, options = {}) {
  const server = createApp(options);
  return new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(Number(port), () => {
      const addr = server.address();
      const actualPort = typeof addr === 'object' && addr ? addr.port : port;
      console.log(`Reading Tracker running at http://localhost:${actualPort}`);
      resolve(server);
    });
  });
}

const isMain =
  process.argv[1] &&
  fileURLToPath(import.meta.url) === process.argv[1];

if (isMain) {
  startServer();
}

