import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { createApp, BookStore } from '../index.js';

describe('Reading Tracker App', () => {
  let tempDir;
  let dataFile;
  let server;
  let baseUrl;

  beforeEach(async () => {
    tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'reading-tracker-'));
    dataFile = path.join(tempDir, 'books.json');
    server = createApp({ filePath: dataFile });
    await new Promise((resolve) => server.listen(0, resolve));
    const { port } = server.address();
    baseUrl = `http://127.0.0.1:${port}`;
  });

  afterEach(async () => {
    if (server && server.listening) {
      await new Promise((resolve) => server.close(resolve));
    }
    if (tempDir && fs.existsSync(tempDir)) {
      fs.rmSync(tempDir, { recursive: true, force: true });
    }
  });

  it('shows currently reading and finished sections on the home page', async () => {
    const res = await fetch(`${baseUrl}/`);
    expect(res.status).toBe(200);
    const html = await res.text();
    expect(html).toContain('Currently Reading');
    expect(html).toContain('Finished');
    expect(html).toContain('Add a Book');
  });

  it('adds a book via form submission, marks it as finished, and persists across restarts', async () => {
    const formBody = new URLSearchParams({
      title: 'Dune',
      author: 'Frank Herbert',
      notes: 'Fear is the mind-killer.',
    });

    const addRes = await fetch(`${baseUrl}/books`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: formBody.toString(),
      redirect: 'manual',
    });
    expect(addRes.status).toBe(303);

    // Verify book is saved to JSON file and shown under Currently Reading
    const booksOnDisk = JSON.parse(fs.readFileSync(dataFile, 'utf8'));
    expect(booksOnDisk).toHaveLength(1);
    expect(booksOnDisk[0].title).toBe('Dune');
    expect(booksOnDisk[0].author).toBe('Frank Herbert');
    expect(booksOnDisk[0].notes).toBe('Fear is the mind-killer.');
    expect(booksOnDisk[0].status).toBe('reading');

    const bookId = booksOnDisk[0].id;

    // Check individual book link / detail page
    const detailRes = await fetch(`${baseUrl}/books/${bookId}`);
    expect(detailRes.status).toBe(200);
    const detailHtml = await detailRes.text();
    expect(detailHtml).toContain('Dune');
    expect(detailHtml).toContain('Frank Herbert');
    expect(detailHtml).toContain('Fear is the mind-killer.');
    expect(detailHtml).toContain(`/books/${bookId}`);

    // Mark as finished
    const finishRes = await fetch(`${baseUrl}/books/${bookId}/finish`, {
      method: 'POST',
      redirect: 'manual',
    });
    expect(finishRes.status).toBe(303);

    // Simulate server restart using the same JSON file
    await new Promise((resolve) => server.close(resolve));
    const restartedServer = createApp({ filePath: dataFile });
    await new Promise((resolve) => restartedServer.listen(0, resolve));
    const restartedPort = restartedServer.address().port;
    const restartedUrl = `http://127.0.0.1:${restartedPort}`;

    const apiRes = await fetch(`${restartedUrl}/api/books`);
    const booksAfterRestart = await apiRes.json();
    expect(booksAfterRestart).toHaveLength(1);
    expect(booksAfterRestart[0].id).toBe(bookId);
    expect(booksAfterRestart[0].status).toBe('finished');
    expect(booksAfterRestart[0].finished).toBe(true);

    await new Promise((resolve) => restartedServer.close(resolve));
  });

  it('supports JSON API endpoints for adding, listing, viewing, and finishing books', async () => {
    const createRes = await fetch(`${baseUrl}/api/books`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        title: 'Project Hail Mary',
        author: 'Andy Weir',
        notes: 'Amaze! Amaze! Amaze!',
      }),
    });
    expect(createRes.status).toBe(201);
    const created = await createRes.json();
    expect(created.id).toBeTruthy();
    expect(created.status).toBe('reading');

    const singleRes = await fetch(`${baseUrl}/api/books/${created.id}`);
    expect(singleRes.status).toBe(200);
    const single = await singleRes.json();
    expect(single.title).toBe('Project Hail Mary');
    expect(single.author).toBe('Andy Weir');
    expect(single.notes).toBe('Amaze! Amaze! Amaze!');

    const finishRes = await fetch(`${baseUrl}/api/books/${created.id}/finish`, {
      method: 'POST',
    });
    expect(finishRes.status).toBe(200);
    const finished = await finishRes.json();
    expect(finished.status).toBe('finished');
    expect(finished.finished).toBe(true);

    const store = new BookStore(dataFile);
    expect(store.getById(created.id).finished).toBe(true);
  });
});

